function I.set(l) if l == "hu" or l == "de" or l == "en" then I.lang = l end end
function I.get() return I.lang end
function I.tr(s)
  if I.lang == "hu" then return s end
  local e = I.map[s]
  if e and e[I.lang] then return e[I.lang] end
  return s
end

return I
